approved_command_preview:
$ErrorActionPreference = 'Stop'
$token = $env:DCOIR_GITHUB_CL_TOKEN
if ([string]::IsNullOrWhiteSpace($token)) { throw 'The classic GitHub token is not available to the runner.' }
$env:GH_TOKEN = $token
$before = gh api repos/malwaredevil/dcoir-collector/pulls/465 | ConvertFrom-Json
if (-not $before.draft) { Write-Output ('PR #465 is already Ready at head ' + $before.head.sha); exit 0 }
gh pr ready 465 --repo malwaredevil/dcoir-collector
$after = gh api repos/malwaredevil/dcoir-collector/pulls/465 | ConvertFrom-Json
if ($after.draft) { throw 'PR #465 remained Draft after the approved Ready transition.' }
Write-Output ('PR #465 is Ready; head=' + $after.head.sha + '; state=' + $after.state)

